<?php
namespace App\Controllers; use App\Controllers\BaseController; use App\Models\ProjectDecisionModel; use App\Models\ProjectCommitmentModel; use CodeIgniter\HTTP\ResponseInterface;
class DecisionCommitmentIntelligence extends BaseController { private ProjectDecisionModel $decisions;private ProjectCommitmentModel $commitments;public function __construct(){$this->decisions=new ProjectDecisionModel();$this->commitments=new ProjectCommitmentModel();}public function meeting(int $mid):ResponseInterface{$m=$this->meetingRow($mid);if(!$m)return $this->json(['success'=>false,'message'=>'Meeting not found.'],404);return $this->json(['success'=>true,'decisions'=>$this->decisions->where('meeting_id',$mid)->orderBy('id','DESC')->findAll(),'commitments'=>$this->withPeople($mid)]);}public function syncMeeting(int $mid):ResponseInterface{$m=$this->meetingRow($mid);if(!$m)return $this->json(['success'=>false,'message'=>'Meeting not found.'],404);$db=db_connect();$actor=$this->actorId();$dc=0;$cc=0;if($db->tableExists('meeting_decisions'))foreach($db->table('meeting_decisions')->where('meeting_id',$mid)->get()->getResultArray() as $r){$sid=(int)($r['id']??0);if($sid&&$this->decisions->where('source_type','meeting_decision')->where('source_id',$sid)->first())continue;$text=trim((string)($r['decision_text']??$r['body']??$r['decision']??''));if($text==='')continue;$this->decisions->insert(['project_id'=>(int)$m['project_id'],'meeting_id'=>$mid,'source_type'=>'meeting_decision','source_id'=>$sid?:null,'title'=>mb_substr($text,0,120),'decision_text'=>$text,'rationale'=>$r['reason']??$r['rationale']??null,'status'=>'active','decided_at'=>$m['start_at']??date('Y-m-d H:i:s'),'created_by'=>$actor]);$dc++;}if($db->tableExists('meeting_action_items'))foreach($db->table('meeting_action_items')->where('meeting_id',$mid)->get()->getResultArray() as $r){$sid=(int)($r['id']??0);if($sid&&$this->commitments->where('source_action_item_id',$sid)->first())continue;$title=trim((string)($r['body']??$r['action_text']??$r['title']??''));if($title==='')continue;$this->commitments->insert(['project_id'=>(int)$m['project_id'],'meeting_id'=>$mid,'source_action_item_id'=>$sid?:null,'task_id'=>!empty($r['created_task_id'])?(int)$r['created_task_id']:(!empty($r['task_id'])?(int)$r['task_id']:null),'title'=>$title,'owner_id'=>!empty($r['assignee_id'])?(int)$r['assignee_id']:(!empty($r['suggested_assignee_id'])?(int)$r['suggested_assignee_id']:null),'due_date'=>$r['due_date']??null,'status'=>(!empty($r['created_task_id'])||!empty($r['task_id']))?'in_progress':'open','confidence'=>isset($r['confidence'])?(float)$r['confidence']:null,'notes'=>$r['assignment_reason']??$r['reason']??$r['ai_reason']??null,'created_by'=>$actor]);$cc++;}return $this->json(['success'=>true,'decisions_created'=>$dc,'commitments_created'=>$cc]);}public function updateCommitment(int $id):ResponseInterface{$x=$this->commitments->find($id);if(!$x)return $this->json(['success'=>false,'message'=>'Commitment not found.'],404);$d=$this->input();$st=(string)($d['status']??'');if(!in_array($st,['open','in_progress','fulfilled','missed','cancelled'],true))return $this->json(['success'=>false,'message'=>'Invalid commitment status.'],422);$this->commitments->update($id,['status'=>$st,'fulfilled_at'=>$st==='fulfilled'?date('Y-m-d H:i:s'):null]);return $this->json(['success'=>true,'commitment'=>$this->oneWithPerson($id)]);}public function createTask(int $id):ResponseInterface{$x=$this->commitments->find($id);if(!$x)return $this->json(['success'=>false,'message'=>'Commitment not found.'],404);if(!empty($x['task_id']))return $this->json(['success'=>true,'task_id'=>(int)$x['task_id'],'already_exists'=>true]);$db=db_connect();$fields=$db->getFieldNames('tasks');$task=['project_id'=>(int)$x['project_id'],'body'=>$x['title'],'due_date'=>$x['due_date']?:null,'completed'=>0];foreach(['status'=>'todo','priority'=>'normal','source_type'=>'commitment','source_id'=>$id,'ai_generated'=>1,'ai_reason'=>'Created from reviewed meeting commitment'] as $k=>$v)if(in_array($k,$fields,true))$task[$k]=$v;if(in_array('sort_order',$fields,true)){$max=$db->table('tasks')->where('project_id',$x['project_id'])->selectMax('sort_order')->get()->getRowArray();$task['sort_order']=((int)($max['sort_order']??0))+10;}$db->table('tasks')->insert($task);$tid=(int)$db->insertID();$this->commitments->update($id,['task_id'=>$tid,'status'=>'in_progress']);if(!empty($x['owner_id'])&&$db->tableExists('task_assignments')){$af=$db->getFieldNames('task_assignments');$row=[];foreach(['task_id'=>$tid,'team_member_id'=>(int)$x['owner_id']] as $k=>$v)if(in_array($k,$af,true))$row[$k]=$v;if($row)$db->table('task_assignments')->insert($row);}return $this->json(['success'=>true,'task_id'=>$tid]);}private function withPeople(int $mid):array{return db_connect()->table('project_commitments pc')->select('pc.*,tm.name AS owner_name,tm.photo AS owner_photo,tm.job_title AS owner_job_title')->join('team_members tm','tm.id=pc.owner_id','left')->where('pc.meeting_id',$mid)->orderBy('pc.id','DESC')->get()->getResultArray();}private function oneWithPerson(int $id):array{return db_connect()->table('project_commitments pc')->select('pc.*,tm.name AS owner_name,tm.photo AS owner_photo,tm.job_title AS owner_job_title')->join('team_members tm','tm.id=pc.owner_id','left')->where('pc.id',$id)->get()->getRowArray()?:[];}private function meetingRow(int $id):?array{$db=db_connect();if(!$db->tableExists('meetings'))return null;return $db->table('meetings')->where('id',$id)->get()->getRowArray()?:null;}private function actorId():?int{$id=(int)(session()->get('team_member_id')??0);return $id>0?$id:null;}private function input():array{return $this->request->getJSON(true)?:$this->request->getPost()?:[];}private function json(array $d,int $s=200):ResponseInterface{return $this->response->setStatusCode($s)->setJSON($d);} }
